using MediatR; using JTradeERP.Application.Common.Persistence; using JTradeERP.Application.Common.Exceptions;
namespace JTradeERP.Application.Features.MasterData.TaxCodes.UpdateTaxCode;
public sealed class UpdateTaxCodeHandler(IApplicationDbContext db) : IRequestHandler<UpdateTaxCodeCommand, UpdateTaxCodeResponse> { public async Task<UpdateTaxCodeResponse> Handle(UpdateTaxCodeCommand r, CancellationToken ct) { var e = db.TaxCodes.SingleOrDefault(x => x.Id == r.Id) ?? throw new NotFoundException("Tax code not found."); if (db.TaxCodes.Any(x => x.Id != r.Id && x.Code == r.Code.Trim())) throw new ConflictException("Tax code already exists."); e.Update(r.Code,r.Name,r.Rate,r.TaxType); await db.SaveChangesAsync(ct); return new(e.Id,e.Code,e.Name,e.Rate,e.TaxType,e.IsActive); } }
